304	  private _syncFlameState(root: THREE.Object3D | null): void {
305	    const flameMesh = this._flameMesh;
306	    if (!root || !flameMesh) return;
307	    const flameOptions = this._resolveFlameOptions();
308	    const flameScale = flameOptions.scale ?? DEFAULT_FLAME_SCALE;
309	    const flameOffset = flameOptions.offset ?? DEFAULT_FLAME_OFFSET;
310	    const anchor = this._flameAnchor;
311	    if (anchor && flameMesh.parent !== anchor) {
312	      anchor.add(flameMesh);
313	    } else if (!anchor && flameMesh.parent !== root) {
314	      root.add(flameMesh);
315	    }
316	
317	    flameMesh.visible = flameOptions.visible !== false && root.visible;
318	    if (anchor && flameMesh.parent === anchor) {
319	      const ox = flameOffset?.x ?? DEFAULT_FLAME_OFFSET.x;
320	      const oy = flameOffset?.y ?? DEFAULT_FLAME_OFFSET.y;
321	      const oz = flameOffset?.z ?? DEFAULT_FLAME_OFFSET.z;
322	      flameMesh.position.set(ox, oy, oz);
323	    } else {
324	      const flamePosition = this._resolveFlamePosition(flameOffset);
325	      flameMesh.position.set(flamePosition.x, flamePosition.y, flamePosition.z);
326	    }
327	    flameMesh.scale.set(
328	      flameScale.x ?? DEFAULT_FLAME_SCALE.x,
329	      flameScale.y ?? DEFAULT_FLAME_SCALE.y,
330	      flameScale.z ?? DEFAULT_FLAME_SCALE.z,
331	    );
332	    flameMesh.renderOrder = this._resolveFlameRenderOrder(flameOptions);
333	    flameMesh.material.uniforms.uOpacity.value =
334	      this._resolveFlameOpacity(flameOptions);
335	    flameMesh.material.uniforms.uFlameSpeed.value =
336	      this._resolveFlameSpeed(flameOptions);
337	    flameMesh.material.uniforms.uWaveStrength.value =
338	      this._resolveFlameWave(flameOptions);
339	    this._syncFlameBillboard();
340	  }
341	
342	  private _syncFlameBillboard(): void {
343	    const root = this.getTimelineRoot();
344	    const flameMesh = this._flameMesh;
345	    const camera = this._context?.camera;
346	    if (!root || !flameMesh || !camera) return;
347	
348	    camera.getWorldQuaternion(this._cameraWorldQuaternion);
349	    root.getWorldQuaternion(this._rootWorldQuaternion);
350	    this._rootWorldQuaternion.invert();
351	    flameMesh.quaternion
352	      .copy(this._rootWorldQuaternion)
353	      .multiply(this._cameraWorldQuaternion);
354	    const flameRotation = this._resolveFlameRotation(
355	      this._resolveFlameOptions(),
356	    );
357	    this._flameLocalEuler.set(
358	      THREE.MathUtils.degToRad(flameRotation.x),
359	      THREE.MathUtils.degToRad(flameRotation.y),
360	      THREE.MathUtils.degToRad(flameRotation.z),
361	    );
362	    this._flameLocalQuaternion.setFromEuler(this._flameLocalEuler);
363	    flameMesh.quaternion.multiply(this._flameLocalQuaternion);
364	  }
