78	        this.surgeTimer = 0;
79	        this.nextBurst = (0.01 + Math.random() * 0.08) / spd;
80	      }
81	    }
82	
83	    this.smoothLen += (target - this.smoothLen) * c.smoothing;
84	    const flameLen = Math.max(
85	      base - 0.02,
86	      Math.min(base + 0.3, this.smoothLen),
87	    );
88	    return { flameLen, throttle: Math.min(1, flameLen), elapsed: this.elapsed };
