49	  state: Record<string, unknown> | null,
50	): Record<string, unknown> | null {
51	  if (!state) return null;
52	  const sheetsByIdValue = state.sheetsById;
53	  if (
54	    sheetsByIdValue == null ||
55	    typeof sheetsByIdValue !== "object" ||
56	    Array.isArray(sheetsByIdValue)
57	  ) {
58	    return state;
59	  }
60	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
61	  const nextSheetsById: Record<string, unknown> = {};
62	  MAIN_THEATRE_SHEET_IDS.forEach((sheetId) => {
63	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
64	    nextSheetsById[sheetId] = sheetsById[sheetId];
65	  });
66	  return {
67	    ...state,
68	    sheetsById: nextSheetsById,
69	  };
70	}
